-- Mod-authored splash painting descriptions for World Congress special
-- sessions and projects, it_IT overlay.
-- Baseline in CivVAccess_CongressDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_MISSING"] = "Nessuna descrizione per questa immagine."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_SPECIAL_SESSION_START_WORLD_CONGRESS"] =
    "Un'assemblea in seduta, vista dalla parte posteriore della sala sopra le teste del pubblico. In fondo, i delegati siedono attorno a un lungo tavolo drappeggiato di rosso su una pedana tappezzata, con un foglio di carta bianca davanti a ciascun posto. Una figura in vesti bianche e copricapo bianco sta in piedi a capotavola per rivolgersi alla sala, con un uomo dalla barba scura al suo fianco. Il pubblico li guarda dalle file di sedie di legno, turbanti e calotte e teste scoperte insieme. Altri astanti osservano da tra le pallide colonne lungo la parete destra."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_PROJECT_WORLD_FAIR"] =
    "Una grande ruota panoramica sale fuori dal bordo superiore del quadro a destra, le cabine chiuse per i passeggeri appese al suo bordo. La sua base scende dietro un grande arco di ferro rivettato verde, che scavalca una parete chiara con la scritta FERRIS WHEEL. I visitatori della fiera attraversano il vasto piazzale polveroso sotto: donne in lunghi abiti, uomini in soprabiti e bombette e cappelli a cilindro. Bassi padiglioni con insegne dipinte si allineano lungo il viale a sinistra, dove in lontananza si erge una grande sala a cupola bianca sotto un cielo azzurro pallido."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_PROJECT_WORLD_GAMES"] =
    "I primi passi di una gara: quattro corridori si lanciano in avanti dalla linea di partenza, le teste chine, su una pista scura che attraversa il primo piano. Alle loro spalle a sinistra, lo starter sta in piedi in un lungo cappotto bianco, la pistola alzata ancora fumante. Le tribune gremite riempiono tutto lo sfondo, la folla abbozzata come macchie di colore. Scalette bianche e alti pali fiancheggiano la pista a destra, e il verde del campo si distende oltre di essi."
